import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        StreamTokenizerLite t = new StreamTokenizerLite(br);
        String a = t.next(), b = t.next(), c = t.next();
        int n = a.length(), chosen = -1;
        for (int i = 0; i < n; i++)
            if (c.charAt(i) != a.charAt(i) && c.charAt(i) != b.charAt(i)) chosen = i;
        if (chosen < 0) {
            System.out.println("-1");
            return;
        }
        byte[] full = new byte[28], shortClass = new byte[27];
        full[0] = '[';
        shortClass[0] = '[';
        int s = 1;
        for (int k = 0; k < 26; k++) {
            byte ch = (byte) ('A' + k);
            full[k + 1] = ch;
            if (ch != c.charAt(chosen)) shortClass[s++] = ch;
        }
        full[27] = ']';
        shortClass[26] = ']';
        BufferedOutputStream out = new BufferedOutputStream(System.out, 1 << 16);
        for (int i = 0; i < n; i++) out.write(i == chosen ? shortClass : full);
        out.write('\n');
        out.flush();
    }

    // Reads whitespace-separated tokens across lines.
    static class StreamTokenizerLite {
        final BufferedReader br;
        java.util.StringTokenizer st;

        StreamTokenizerLite(BufferedReader br) {
            this.br = br;
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) st = new java.util.StringTokenizer(br.readLine());
            return st.nextToken();
        }
    }
}

package main

import (
	"bufio"
	"os"
)

func main() {
	reader := bufio.NewReaderSize(os.Stdin, 1<<20)
	readToken := func() []byte {
		var tok []byte
		c, err := reader.ReadByte()
		for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
			c, err = reader.ReadByte()
		}
		for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
			tok = append(tok, c)
			c, err = reader.ReadByte()
		}
		return tok
	}
	a, b, c := readToken(), readToken(), readToken()
	n, chosen := len(a), -1
	for i := 0; i < n; i++ {
		if c[i] != a[i] && c[i] != b[i] {
			chosen = i
		}
	}
	w := bufio.NewWriterSize(os.Stdout, 1<<20)
	defer w.Flush()
	if chosen < 0 {
		w.WriteString("-1\n")
		return
	}
	full := []byte("[ABCDEFGHIJKLMNOPQRSTUVWXYZ]")
	short := []byte{'['}
	for ch := byte('A'); ch <= 'Z'; ch++ {
		if ch != c[chosen] {
			short = append(short, ch)
		}
	}
	short = append(short, ']')
	for i := 0; i < n; i++ {
		if i == chosen {
			w.Write(short)
		} else {
			w.Write(full)
		}
	}
	w.WriteByte('\n')
}
